files.automation.schema:
// automation.schema — multi-step automations, their runs, and notifications.

namespace veil

import { Entity, RecordRef } from "./common"
import { Filter } from "./user"

enum TriggerKind {
  /// A user event happened (EventKind in eventKinds).
  1 event
  /// A cron schedule.
  2 schedule
  /// A follow found new media.
  3 newMedia
  /// A followed cam model went live.
  4 camLive
  /// A file appeared in a library root.
  5 fileAdded
  /// A wanted record was found.
  6 wantedFound
  /// Contributed by a plugin (pluginTrigger names it).
  7 plugin
}

@value
model Trigger {
  1 kind: TriggerKind
  /// Cron expression for schedule triggers.
  2 cron: string?
  3 eventKinds: [string]?
  /// Only fire for records matching this filter.
  4 filter: Filter?
  /// "<plugin>:<trigger>" for plugin triggers.
  5 pluginTrigger: string?
}

/// One step. Built-in actions: download, record, tag, addToCollection,
/// notify, moveFile, delete, archive, lookup, runPlugin; plugins add
/// "<plugin>:<action>".
@value
model Step {
  1 action: string
  2 args: json?
  /// Skip the step unless its input matches.
  3 condition: Filter?
  4 continueOnError: bool
}

/// A multi-step automation: when the trigger fires, the steps run in order,
/// each seeing the previous step's output.
model Automation extends Entity {
  10 name: string
  11 enabled: bool
  12 trigger: Trigger
  13 steps: [Step]
  /// Built-in automations (the wanted hunt) can be tuned but not deleted.
  14 builtIn: bool
}

enum RunStatus {
  1 running
  2 succeeded
  3 failed
  4 undone
}

@value
model StepResult {
  1 action: string
  2 ok: bool
  3 output: json?
  4 error: string?
  /// Records the step touched.
  5 touched: [RecordRef]
}

/// One run of an automation. Undoing it reverts the revisions it wrote.
@index(fields: ["automation", "startedAt"])
model AutomationRun extends Entity {
  10 automation: ref<Automation>

  11 startedAt: timestamp
  12 finishedAt: timestamp?
  13 status: RunStatus
  /// Preview only: steps reported what they would do.
  14 dryRun: bool
  15 triggerData: json?
  16 steps: [StepResult]
}

enum ChannelKind {
  1 inApp
  2 push
  3 ntfy
  4 webhook
}

/// Where notifications go.
model NotificationChannel extends Entity {
  10 kind: ChannelKind
  11 name: string
  /// Topic and server for ntfy, URL for webhooks, device for push.
  12 config: json?
  13 enabled: bool
}

@index(fields: ["read", "at"])
model Notification extends Entity {
  10 at: timestamp
  /// "newMedia", "camLive", "downloadDone", "automationFailed", …
  11 kind: string
  12 title: string
  13 body: string?
  14 subject: RecordRef?
  15 read: bool
}

files.classification.schema:
// classification.schema — site tags, our own categories, and the user's
// custom fields.

namespace veil

import { Entity, Asset, RecordKind } from "./common"

/// A site's own label. Never curated or browsed, only used to filter.
@index(fields: ["nameKey"], unique: true)
model Tag extends Entity {
  10 name: string
  11 aliases: [string]

  /// The name folded for comparison (internal/names.Key), so spellings of
  /// the same tag land on one row.
  12 nameKey: string
}

/// Our own taxonomy, defined by us rather than any site. Media belongs to a
/// category when it carries any of the category's tags, so new site tags only
/// need mapping, never re-tagging.
model Category extends Entity {
  10 name: string

  @unique
  11 slug: string

  12 parent: ref<Category>?
  13 matchTags: [ref<Tag>]

  14 cover: Asset?
  15 position: i32
}

/// The value type of a custom field.
enum FieldType {
  1 text
  2 number
  3 boolean
  4 date
  5 choice
  6 choices
  7 url
}

/// A field the user added to some kinds of records. Values live in
/// UserState.fields under the definition's id, so filters and automation
/// conditions can use them.
model FieldDef extends Entity {
  10 name: string
  11 kinds: [RecordKind]
  12 fieldType: FieldType
  /// Allowed values for choice fields.
  13 options: [string]?
}

files.common.schema:
// common.schema — building blocks every other file uses: the Entity base,
// polymorphic references, assets and sources.
//
// Decorators only appear where they change generated output:
//   @abstract  shared base, never stored on its own; GraphQL interface
//              (openschema#3)
//   @value     value object stored inline as JSON, never a table
//   @index     composite index on a table
//   ref<T>     (a type, not a decorator) the id of a T record
//
// Backend behaviour lives in comments: every write is recorded as a Revision
// (except high-volume logs: events, jobs, streams), and plugins fill the
// descriptive fields of media, performers, studios and groups, with
// FieldSource tracking which source owns each.

namespace veil

/// Every kind of stored record. Polymorphic references (subjectKind +
/// subjectId) name the table through this.
enum RecordKind {
  1 video
  2 gallery
  3 image
  4 audio
  5 story
  6 post
  7 performer
  8 studio
  9 camModel
  10 group
  11 tag
  12 category
  13 collection
  14 segment
  15 clip
}

/// The kinds of media: the things you watch, view, listen to or read.
enum MediaKind {
  1 video
  2 gallery
  3 audio
  4 story
  5 post
}

/// Who or what wrote a value.
enum Actor {
  1 user
  2 plugin
  3 automation
  4 system
}

/// Fields every stored record has. Ids are uuids so records stay unique
/// across devices once sync arrives. Deleting trashes a record (deletedAt);
/// it's purged once the trash retention passes.
@abstract
model Entity {
  @primaryKey
  1 id: uuid

  @default(now())
  2 createdAt: timestamp

  @default(now())
  3 updatedAt: timestamp

  /// Set when trashed; the row is purged once the trash retention passes.
  4 deletedAt: timestamp?
}

/// A reference to any record, for lists that mix kinds.
@value
model RecordRef {
  1 kind: RecordKind
  2 id: uuid
}

/// A picture or clip: a stored blob (`blob://…`) or a remote URL.
@value
model Asset {
  1 uri: string
  2 mimeType: string?
  3 width: i32?
  4 height: i32?
  /// Compact placeholder shown while the asset loads.
  5 blurhash: string?
}

/// Where a record came from: one entry per site it was scraped or merged
/// from. Merging two records moves their sources onto the survivor.
@index(fields: ["plugin", "externalId"], unique: true)
model Source extends Entity {
  10 subjectKind: RecordKind
  11 subjectId: uuid

  /// Plugin name, e.g. "xvideos".
  12 plugin: string
  /// The plugin's stable id for the record on its site.
  13 externalId: string
  14 url: string

  /// Short label and thumbnail, so a source can be shown as evidence.
  15 title: string?
  16 image: Asset?

  /// Archived copy of the page and media, in case the site removes it.
  17 snapshot: Asset?
  18 fetchedAt: timestamp?
}

files.content.schema:
// content.schema — the media: videos, galleries and their images, audio,
// stories, and creator-platform posts.

namespace veil

import { Entity, Asset, RecordRef } from "./common"
import { Tag } from "./classification"
import { Performer, Studio, CamModel, Group } from "./people"

/// Whether we have the media or only know it exists.
enum MediaStatus {
  /// Playable or viewable from a stored file or a live source.
  1 available
  /// Known to exist (a filmography, a catalog) but not found yet; the
  /// wanted hunt keeps searching for it.
  2 wanted
  /// Was available, every source and file is gone.
  3 unavailable
}

/// Fields every piece of media shares. Categories are not stored: they follow
/// from the tags. Plugins fill the descriptive fields; FieldSource records
/// which source owns each one.
@abstract
model Media extends Entity {
  10 title: string

  11 details: string?

  12 date: date?

  13 cover: Asset?

  14 studio: ref<Studio>?
  15 performers: [ref<Performer>]
  16 tags: [ref<Tag>]

  17 status: MediaStatus
}

/// How a VR video is projected.
enum VrProjection {
  1 equirectangular180
  2 equirectangular360
  3 fisheye
  4 cubemap
}

/// How a VR video packs the two eyes.
enum VrStereo {
  1 mono
  2 sideBySide
  3 topBottom
}

@value
model VrFormat {
  1 projection: VrProjection
  2 stereo: VrStereo
  3 fieldOfView: i32?
}

/// The thumbnail grid shown while scrubbing the seek bar: frames every
/// intervalSeconds, packed into one or more sprite sheets.
@value
model Trickplay {
  1 sheets: [Asset]
  2 columns: i32
  3 rows: i32
  4 tileWidth: i32
  5 tileHeight: i32
  6 intervalSeconds: f32
}

model Video extends Media {
  30 durationSeconds: f64?

  31 width: i32?
  32 height: i32?
  33 vr: VrFormat?

  /// Short hover clip.
  34 preview: Asset?

  35 trickplay: Trickplay?

  /// The photo set shot alongside it.
  36 gallery: ref<Gallery>?

  /// Set when this is a cam recording.
  37 recordedFrom: ref<CamModel>?

  /// Evenly spaced stills from the site's listing, in order; cards scrub
  /// through them on hover.
  38 previewFrames: [Asset]?
}

/// A video's place in a site group.
@index(fields: ["group", "video"], unique: true)
model GroupItem extends Entity {
  10 group: ref<Group>
  11 video: ref<Video>

  12 position: i32
}

/// A photo set.
model Gallery extends Media {
  30 imageCount: i32

  /// The video shot alongside it.
  31 video: ref<Video>?
}

/// A photo. Always belongs to a gallery.
@index(fields: ["gallery", "position"])
model Image extends Entity {
  10 gallery: ref<Gallery>

  11 position: i32
  12 asset: Asset
  13 width: i32?
  14 height: i32?
}

/// Erotic audio and ASMR. Performers are the voices.
model Audio extends Media {
  30 durationSeconds: f64?
}

/// Erotic fiction, read chapter by chapter.
model Story extends Media {
  30 chapterCount: i32
  31 wordCount: i32?
  32 complete: bool
}

@index(fields: ["story", "position"], unique: true)
model StoryChapter extends Entity {
  10 story: ref<Story>

  11 position: i32
  12 title: string?
  /// Empty until read: chapters a story lists without their text are read
  /// on demand from url.
  13 text: string
  14 wordCount: i32
  15 url: string?
}

/// A post on a creator platform. It wraps ordinary media; the creator is a
/// Performer, so following a creator is following a performer.
model Post extends Media {
  30 creator: ref<Performer>

  31 text: string?

  /// Videos, galleries, audio or stories attached to the post.
  32 attachments: [RecordRef]

  /// Paywalled for the logged-in account.
  33 locked: bool
  34 priceCents: i64?
  35 currency: string?
}

files.features.schema:
// features.schema — features are functions over the core records: they take
// an input and return matches, each saying why it's there. Plugins add
// lookups; the backend adds feeds.

namespace veil

import { RecordRef, Asset } from "./common"
import { Filter } from "./user"

/// Why a match is there: a solved NameThatPorn thread, a face match, "because
/// you watched …".
@value
model Evidence {
  /// Plugin name, or "veil" for the backend's own features.
  1 plugin: string
  2 url: string?
  3 title: string?
  4 image: Asset?
  /// e.g. "94% face match", "accepted answer".
  5 detail: string?
}

/// A record a feature found, with its score and evidence.
@value
model Match {
  1 item: RecordRef
  @minValue(0) @maxValue(1)
  2 score: f32?
  3 evidence: [Evidence]
}

/// A lookup input: text, a picture, or both.
@value
model LookupQuery {
  1 text: string?
  2 imageBase64: bytes?
  3 mimeType: string?
  /// Restrict to these plugins.
  4 plugins: [string]?
}

/// Every identification plugin, merged: face search, NameThatPorn, …
@query op lookup(query: LookupQuery): [Match]

/// Ranked recommendations, each with its reasons.
@query op recommendations(limit: i32?, offset: i32?): [Match]

/// Records related to one record (same performer, similar frames, …).
@query op related(item: RecordRef, limit: i32?): [Match]

/// The vertical shorts feed: clips, segments, short vertical videos and post
/// attachments.
@query op shorts(filter: Filter?, limit: i32?): [Match]

files.people.schema:
// people.schema — who appears and who made it: performers, studios, cam
// models, and site groups (movies, series, compilations).

namespace veil

import { Entity, Asset } from "./common"
import { Tag } from "./classification"

/// Body and career facts, filled by plugins as far as they know them.
@value
model PerformerAttributes {
  1 gender: string?
  2 birthdate: date?
  3 deathDate: date?
  4 country: string?
  5 ethnicity: string?
  6 eyeColor: string?
  7 hairColor: string?
  8 heightCm: i32?
  9 weightKg: i32?
  10 measurements: string?
  11 fakeTits: string?
  12 tattoos: string?
  13 piercings: string?
  14 careerStart: i32?
  15 careerEnd: i32?
}

/// A person who appears in media.
@index(fields: ["nameKey"])
model Performer extends Entity {
  10 name: string

  11 aliases: [string]

  12 image: Asset?

  13 details: string?

  14 attributes: PerformerAttributes

  /// Socials and official sites.
  15 links: [string]

  16 tags: [ref<Tag>]

  /// The name folded for comparison (internal/names.Key).
  17 nameKey: string
}

/// A production company, channel or network.
@index(fields: ["nameKey"])
model Studio extends Entity {
  10 name: string

  11 aliases: [string]

  12 image: Asset?

  13 details: string?

  14 parent: ref<Studio>?

  15 url: string?

  16 tags: [ref<Tag>]

  /// The name folded for comparison (internal/names.Key).
  17 nameKey: string
}

/// What a cam room is doing right now; null on the model when offline.
@value
model CamLive {
  1 viewers: i32
  2 subject: string?
  3 startedAt: timestamp?
  4 thumbnail: Asset?
}

/// A room on one cam site. Live state comes from the site's plugin;
/// recordings become Videos with recordedFrom set.
@index(fields: ["plugin", "username"], unique: true)
model CamModel extends Entity {
  10 plugin: string
  11 username: string
  12 displayName: string

  /// The same person in the library, once known.
  13 performer: ref<Performer>?

  14 thumbnail: Asset?
  15 tags: [string]
  16 gender: string?
  17 live: CamLive?
  18 lastSeenOnlineAt: timestamp?

  19 autoRecord: bool
  20 recordQuality: string?
}

/// A site's own grouping of videos: a movie, a series, a compilation.
/// Unlike a Collection it comes from sites, not from the user.
model Group extends Entity {
  10 title: string

  11 details: string?

  12 date: date?

  13 cover: Asset?

  14 studio: ref<Studio>?
}

files.playback.schema:
// playback.schema — how media plays and where its files live: streams,
// stored files, storage locations, library folders, and the time-based
// extras (segments, clips, subtitles, scripts).

namespace veil

import { Entity, RecordKind, Actor, Asset, Source } from "./common"
import { Tag } from "./classification"
import { Performer } from "./people"
import { Video } from "./content"
import { Device } from "./system"

/// A playable stream a source offers, ranked by quality and measured speed.
/// Signed URLs expire and are resolved again from the source page.
@index(fields: ["subjectKind", "subjectId"])
model Stream extends Entity {
  10 subjectKind: RecordKind
  11 subjectId: uuid

  12 source: ref<Source>

  13 url: string
  14 mimeType: string
  15 quality: string?
  16 height: i32?
  17 headers: {string: string}
  18 expiresAt: timestamp?

  /// Last measured throughput, used to rank streams.
  19 speedKbps: i32?
}

enum StorageKind {
  /// Kept: the user's library.
  1 library
  /// Evicted when over quota.
  2 cache
  /// Source snapshots.
  3 archive
}

/// A place on one device where Veil keeps files.
model StorageLocation extends Entity {
  10 device: ref<Device>

  11 kind: StorageKind
  /// A local path or a remote URI (NAS share, object storage).
  12 uri: string
  13 quotaBytes: i64?
  14 usedBytes: i64
}

/// A folder of the user's own files, scanned into the library.
model LibraryRoot extends Entity {
  10 location: ref<StorageLocation>

  11 path: string
  12 scanIntervalMinutes: i32?
  13 lastScanAt: timestamp?

  /// Rename and move template, e.g. "{studio}/{date} {title}.{ext}".
  /// Null leaves files where they are.
  14 organizeTemplate: string?
}

/// A stored file of a media record (or one of its images).
@index(fields: ["location", "path"], unique: true)
model MediaFile extends Entity {
  10 subjectKind: RecordKind
  11 subjectId: uuid

  12 location: ref<StorageLocation>

  /// Relative to the location.
  13 path: string
  14 sizeBytes: i64
  15 mimeType: string
  16 quality: string?
  17 width: i32?
  18 height: i32?
  19 durationSeconds: f64?

  /// Found in a library root rather than downloaded.
  20 libraryRoot: ref<LibraryRoot>?

  /// The file vanished from disk since the last scan.
  21 missing: bool
}

enum SegmentOrigin {
  1 user
  2 plugin
  3 ai
}

/// A time range in a video or audio: a scene within a compilation, a chapter,
/// or a marker (end omitted). Credits on a segment narrow the media's own.
@index(fields: ["subjectKind", "subjectId"])
model Segment extends Entity {
  10 subjectKind: RecordKind
  11 subjectId: uuid

  12 startSeconds: f64
  13 endSeconds: f64?

  14 title: string?

  15 tag: ref<Tag>?
  16 performers: [ref<Performer>]

  17 origin: SegmentOrigin
}

/// A moment the user saved from a video, playable in the shorts feed and
/// exportable as a file.
model Clip extends Entity {
  10 video: ref<Video>

  11 startSeconds: f64
  12 endSeconds: f64
  13 title: string?
  14 cover: Asset?

  /// The exported mp4 or GIF.
  15 file: ref<MediaFile>?
}

enum SubtitleOrigin {
  1 site
  2 generated
  3 translated
}

@index(fields: ["subjectKind", "subjectId"])
model Subtitle extends Entity {
  10 subjectKind: RecordKind
  11 subjectId: uuid

  /// BCP 47, e.g. "en", "ja".
  12 language: string
  /// "vtt", "srt", "ass".
  13 format: string
  14 asset: Asset
  15 origin: SubtitleOrigin
}

enum ScriptKind {
  1 funscript
}

/// A motion script for connected toys, synced to the media's timeline.
@index(fields: ["subjectKind", "subjectId"])
model Script extends Entity {
  10 subjectKind: RecordKind
  11 subjectId: uuid

  12 kind: ScriptKind
  13 asset: Asset

  /// Axis name for multi-axis scripts, e.g. "stroke", "twist".
  14 axis: string?
  15 writtenBy: Actor
}

files.provenance.schema:
// provenance.schema — where values came from and how they changed:
// per-field provenance, revisions, fingerprints, embeddings, loose
// duplicates, and site comments.

namespace veil

import { Entity, RecordKind, Actor, Source } from "./common"
import { Performer } from "./people"

/// Which source a field's value currently comes from. Re-scrapes only update
/// fields their source owns; a locked field keeps the user's value forever.
/// Fields are named by ordinal, so renaming a field keeps its provenance.
@index(fields: ["subjectKind", "subjectId", "fieldOrdinal"], unique: true)
model FieldSource extends Entity {
  10 subjectKind: RecordKind
  11 subjectId: uuid
  12 fieldOrdinal: u32

  13 writtenBy: Actor

  /// The winning source when a plugin wrote it.
  14 source: ref<Source>?

  15 locked: bool
}

/// One field change. Undoing an automation run reverts its revisions.
@index(fields: ["subjectKind", "subjectId"])
model Revision extends Entity {
  10 subjectKind: RecordKind
  11 subjectId: uuid
  12 fieldOrdinal: u32

  13 before: json?
  14 after: json?

  15 writtenBy: Actor
  /// Plugin or automation name.
  16 actorName: string?
  17 automationRunId: uuid?
}

enum FingerprintAlgorithm {
  1 phash
  2 oshash
  3 md5
  4 audio
}

/// A content hash of a file or stream. Matching fingerprints prove two
/// records are the same media, which strict merging relies on.
@index(fields: ["algorithm", "value"])
model Fingerprint extends Entity {
  10 subjectKind: RecordKind
  11 subjectId: uuid

  /// The file it was computed from; null when computed from a stream.
  12 fileId: uuid?

  13 algorithm: FingerprintAlgorithm
  14 value: string
  15 durationSeconds: f64?
}

enum EmbeddingKind {
  1 face
  2 visual
  3 text
}

/// A vector for similarity search: faces for identification, frames for
/// "more like this", text for semantic search.
@index(fields: ["kind", "model"])
model Embedding extends Entity {
  10 subjectKind: RecordKind
  11 subjectId: uuid
  12 kind: EmbeddingKind

  /// Model name and version, so vectors from different models never mix.
  13 model: string
  14 vector: bytes

  /// Where in the media: a frame time and, for faces, the box.
  15 atSeconds: f64?
  16 region: json?
}

/// Two records that are probably the same. Hidden from lists, never merged.
@index(fields: ["subjectKind", "firstId", "secondId"], unique: true)
model Alike extends Entity {
  10 subjectKind: RecordKind
  11 firstId: uuid
  12 secondId: uuid
  13 score: f32
  14 reason: string?

  /// The user said they're different.
  15 dismissed: bool
}

/// A comment from a site, kept per source. Names in it can point to the
/// performer.
@index(fields: ["source"])
model Comment extends Entity {
  10 source: ref<Source>

  11 author: string?
  12 text: string
  13 postedAt: timestamp?
  14 likes: i32?
  15 replyTo: uuid?

  /// Library performers named in the text.
  16 mentions: [ref<Performer>]
}

files.system.schema:
// system.schema — devices, background jobs, API tokens and plugins.

namespace veil

import { Entity, RecordRef, MediaKind } from "./common"

enum Platform {
  1 server
  2 desktop
  3 android
  4 tv
  5 vr
}

/// An install of Veil. Sync, accounts, storage and events are per device.
model Device extends Entity {
  10 name: string
  11 platform: Platform
  12 lastSeenAt: timestamp?
  13 lastSyncAt: timestamp?
  /// This install's own row.
  14 current: bool
}

enum JobKind {
  1 download
  2 record
  3 scrape
  4 followRun
  5 fingerprint
  6 embed
  7 trickplay
  8 transcode
  9 libraryScan
  10 automationRun
  11 snapshot
  12 enrich
  13 speedCheck
}

enum JobStatus {
  1 queued
  2 running
  3 succeeded
  4 failed
  5 cancelled
}

/// Background work, run on one device.
@index(fields: ["status", "runAt"])
@index(fields: ["dedupeKey"], unique: true)
model Job extends Entity {
  10 kind: JobKind
  11 status: JobStatus
  12 subject: RecordRef?
  13 payload: json?

  @minValue(0) @maxValue(1)
  14 progress: f32
  15 error: string?
  16 attempts: i32

  17 runAt: timestamp
  18 startedAt: timestamp?
  19 finishedAt: timestamp?

  20 device: ref<Device>?

  /// The plugin the job runs, when it runs one.
  21 plugin: string?
  /// At most one job per key; enqueueing the same key again reuses it.
  22 dedupeKey: string?
  23 priority: i32
}

/// A global or per-plugin setting. Plugin is empty for global settings.
@index(fields: ["plugin", "key"], unique: true)
model Setting extends Entity {
  10 plugin: string
  11 key: string
  12 value: json?
}

/// A short-lived cached value: stream sessions, resolved URLs, profile pages.
model CacheEntry {
  @primaryKey
  1 key: string
  2 value: string
  /// Unix seconds; null never expires.
  3 expiresAt: i64?
}

/// Access for other clients: a phone streaming from the home server,
/// scripts, agents over MCP.
model ApiToken extends Entity {
  10 name: string
  /// "read", "write", "stream", "admin".
  11 scopes: [string]

  @invisible
  12 tokenHash: bytes

  13 lastUsedAt: timestamp?
  14 expiresAt: timestamp?
}

enum ContributionKind {
  /// Finds and lists records on a site (find/list capabilities).
  1 source
  /// Text or image → matches (face search, namethatporn).
  2 lookup
  /// Resolves pages to playable streams.
  3 stream
  /// Lists live cam rooms.
  4 cams
  5 trigger
  6 action
  /// A feed or home shelf.
  7 feed
  /// Field definitions the plugin fills.
  8 field
  /// A login flow for accounts.
  9 login
  /// A declarative view (form, list, detail) rendered natively by each client.
  10 view
}

/// One thing a plugin adds to Veil.
@value
model Contribution {
  1 kind: ContributionKind
  2 name: string
  3 mediaKinds: [MediaKind]?
  /// Domains served, for sources and streams.
  4 domains: [string]?
}

enum PluginOrigin {
  1 store
  2 local
}

/// An installed plugin.
@index(fields: ["name"], unique: true)
model Plugin extends Entity {
  10 name: string
  11 displayName: string?
  12 version: semver
  13 enabled: bool
  14 origin: PluginOrigin
  15 contributions: [Contribution]
  16 settings: json?
}

files.user.schema:
// user.schema — everything the (single) user adds: per-record state,
// collections, filters, follows, the event log, limits and accounts.

namespace veil

import { Entity, RecordKind, MediaKind, Asset } from "./common"
import { MediaStatus } from "./content"
import { Device } from "./system"

/// The user's state on one record: rating, favourite, notes, progress, block,
/// and custom field values.
@index(fields: ["subjectKind", "subjectId"], unique: true)
model UserState extends Entity {
  10 subjectKind: RecordKind
  11 subjectId: uuid

  /// One overall rating, 0..10.
  @minValue(0) @maxValue(10)
  12 rating: f32?

  13 favorite: bool
  14 notes: string?

  /// Hidden from every list and feed (tags, performers, studios).
  15 blocked: bool

  /// Resume point: seconds into a video or audio, image index in a gallery,
  /// chapter in a story.
  16 progress: f64?
  17 viewCount: i32
  18 lastViewedAt: timestamp?

  /// Custom field values by FieldDef id.
  19 fields: {string: json}
}

enum CollectionKind {
  1 user
  /// Built in: things to watch later.
  2 watchlist
  /// Built in: what plays next.
  3 queue
}

/// An ordered list of media.
model Collection extends Entity {
  10 name: string
  11 kind: CollectionKind
  12 details: string?
  13 cover: Asset?
}

@index(fields: ["collection", "position"])
model CollectionItem extends Entity {
  10 collection: ref<Collection>

  11 subjectKind: RecordKind
  12 subjectId: uuid
  13 position: i32
}

enum SortField {
  1 relevance
  2 date
  3 addedAt
  4 title
  5 rating
  6 duration
  7 viewCount
  8 lastViewedAt
  9 random
}

@value
model Sort {
  1 field: SortField
  2 descending: bool
}

/// A condition on a custom field.
@value
model FieldCondition {
  1 fieldDefId: uuid
  /// "eq", "ne", "lt", "gt", "contains", "set", "unset".
  2 operator: string
  3 value: json?
}

/// One filter shape for every list: library pages, search, category pages,
/// saved and smart filters, follows, automation conditions and plugin
/// listings.
@value
model Filter {
  1 kinds: [MediaKind]
  2 text: string?

  3 performerIds: [uuid]?
  4 studioIds: [uuid]?
  5 categoryIds: [uuid]?
  6 includeTagIds: [uuid]?
  7 excludeTagIds: [uuid]?

  /// Plugin names.
  8 sources: [string]?

  9 dateFrom: date?
  10 dateTo: date?
  11 minDurationSeconds: i32?
  12 maxDurationSeconds: i32?
  13 minRating: f32?
  14 status: [MediaStatus]?

  /// Only media with a stored file.
  15 inLibrary: bool?
  16 favorite: bool?
  17 unwatched: bool?
  18 vr: bool?
  19 fields: [FieldCondition]?

  20 sort: Sort?

  /// Lowest frame height in pixels (720, 1080, 2160); narrows videos only.
  21 minHeight: i32?
}

/// A named filter. Every saved filter can also be played as a smart playlist.
model SavedFilter extends Entity {
  10 name: string
  11 filter: Filter
  12 pinned: bool
}

/// Following anything: a performer, studio, cam model, category or search is
/// a follow on a filter that runs on the sites and feeds notifications.
model Follow extends Entity {
  10 name: string
  11 filter: Filter

  /// What was followed, when it's a single record (a performer, a cam model).
  12 targetKind: RecordKind?
  13 targetId: uuid?

  14 intervalHours: i32
  15 enabled: bool
  16 notify: bool

  17 lastRunAt: timestamp?
  18 nextRunAt: timestamp?
  19 lastError: string?
}

enum EventKind {
  1 view
  2 progress
  3 finish
  4 o
  5 search
  6 impression
  7 choice
  8 heatSpan
  9 skip
  10 like
}

/// One thing the user did. History, o-count, most-replayed, recent searches,
/// stats, limits and the recommendation signals are all queries over this log.
@index(fields: ["kind", "at"]) @index(fields: ["subjectKind", "subjectId"])
model Event extends Entity {
  10 at: timestamp
  11 kind: EventKind
  12 subjectKind: RecordKind?
  13 subjectId: uuid?

  /// Kind-specific detail: watched spans, the search text, the choice.
  14 data: json?

  15 device: ref<Device>?

  16 sessionId: uuid?
}

enum LimitKind {
  1 watchTime
  2 sessions
}

enum LimitWindow {
  1 day
  2 week
}

enum LimitAction {
  1 remind
  2 lock
}

/// A usage limit, checked against the event log.
model Limit extends Entity {
  10 kind: LimitKind
  11 window: LimitWindow
  /// Minutes for watch time, a count for sessions.
  12 amount: i32
  13 action: LimitAction
  14 enabled: bool
}

enum AccountStatus {
  1 ok
  2 expired
  3 needsLogin
  4 failed
}

/// A login on a plugin's site. Credentials stay on the device that logged in.
model Account extends Entity {
  10 plugin: string
  11 label: string
  12 status: AccountStatus

  13 device: ref<Device>

  /// Encrypted; never leaves the device or the API.
  @invisible
  14 credentials: bytes?

  /// Cookies or tokens the plugin gets injected; encrypted.
  @invisible
  15 session: bytes?

  16 expiresAt: timestamp?
  17 lastCheckedAt: timestamp?
}

